import sys,math,bisect; sys.path.insert(0,'.')
from GROUND_TRUTH import chomp
s2=math.sqrt(2); a=1+s2/2; b=1+s2
N=2000
diag=[int(l.split()[1]) for l in open('islands/02-renorm/scratch/diag5000.txt')]
tab=chomp.table(rmax=N,qmax=N)
Dset=set(diag); mx=diag[-1]+3
constants=sorted(v for v in range(2,mx) if v not in Dset)
def nconst_lt(x): return bisect.bisect_right(constants,x)
def fdip(n): return sum(1 for aa in range(n,len(diag)) if diag[aa]<diag[n])
# block count c_n = nconst_lt(d_n)+fdip(n) (exact identity, avoid recompute R_n)
c=[None]*(N+1)
for n in range(1,N+1):
    c[n]=nconst_lt(diag[n])+fdip(n)
am1=s2/2
delta=[c[n]-am1*n for n in range(1,N+1)]
print("delta_n = c_n-(sqrt2/2)n range [%.3f,%.3f]"%(min(delta),max(delta)))
# test self-similarity: delta_n + delta_{floor(n*?)} ... try n->n and n-> n shifted by the OTHER family
# value-domain cocycle was D(x)+D(bx). index analog: does delta_n + delta_{m} bounded for m ~ n*b or n/b?
import statistics as st
for scale,lab in [(a,"*alpha"),(b,"*b"),(1/a,"/alpha"),(1/b,"/b")]:
    pairs=[]
    for n in range(1,N+1):
        m=int(n*scale)
        if 1<=m<=N: pairs.append(delta[n-1]+delta[m-1])
    if pairs:
        print(f"  delta_n + delta_{'floor(n'+lab+')} : range [{min(pairs):.3f},{max(pairs):.3f}] mean {st.mean(pairs):.3f}  (N={len(pairs)})")
PY"}

